import { describe, it } from "vitest";

// Unless a test says otherwise, the customer is a newcomer (0 years with MHPCO)
// and the quote is the customer's first contract, so the premium is
// policy base premium + item surcharges + 10 % first insurance + 5 G fee.
//
// Rejection contract: the specification only defines the CLI outcome (non-zero
// exit status, error description on stderr). Chosen reading for the scenario
// processor: a rejected step throws an Error; type and message are unspecified.

describe("MHPCO claim office", () => {
  describe("quote", () => {
    it.todo("empty item list -> premium 5 G (only the processing fee)");
    it.todo("sword -> 100 G base premium -> premium 115 G (100 + 10 first insurance + 5 fee)");
    it.todo("amulet -> 60 G base premium -> premium 71 G (60 + 6 + 5)");
    it.todo("staff -> 80 G base premium -> premium 93 G (80 + 8 + 5)");
    it.todo("potion -> 40 G base premium -> premium 49 G (40 + 4 + 5)");
    it.todo("sword and amulet -> policy base premium 160 G -> premium 181 G (160 + 16 + 5)");
    it.todo("item with an unknown type (broomstick) -> the quote is rejected by throwing an Error");
    it.todo("newcomer with a cursed sword (steel, enchantment 3) -> premium 165 G (100 + 50 curse + 10 + 5)");
    it.todo(
      "cursed sword and plain amulet -> curse surcharge 50 G on the sword only -> premium 231 G (160 + 50 + 16 + 5)",
    );
    it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies -> premium 145 G (100 + 30 + 10 + 5)");
    it.todo("cursed sword with enchantment 5 -> both surcharges apply -> premium 195 G (100 + 50 + 30 + 10 + 5)");
    it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G");
    it.todo("cursed sword with enchantment 4 -> only the curse surcharge -> premium 165 G");
    it.todo("customer with exactly 2 years with MHPCO -> loyalty discount applies -> sword premium 95 G (100 - 20 + 10 + 5)");
    it.todo("customer with 1 year with MHPCO -> no loyalty discount -> sword premium 115 G");
    it.todo(
      "each contract after the first gets the 15 % follow-up discount -> three sword quotes cost 115 G, 100 G, 100 G (100 + 10 - 15 + 5)",
    );
    it.todo(
      "long-standing customer's second contract, cursed sword (steel, enchantment 7) -> premium 160 G (100 + 50 + 30 - 20 + 10 - 15 + 5)",
    );
    it.todo("2 runes -> 50 G base premium -> premium 60 G (50 + 5 + 5)");
    it.todo("3 runes -> 60 G base premium (block applies) -> premium 71 G (60 + 6 + 5)");
    it.todo("4 runes -> 100 G base premium (no block: a block requires exactly 3) -> premium 115 G (100 + 10 + 5)");
    it.todo("fractional premium is rounded up in the MHPCO's favor -> 1 rune: 25 + 2.5 + 5 = 32.5 -> premium 33 G");
    it.todo("7 runes -> 175 G base premium -> premium 198 G (175 + 17.5 + 5 = 197.5, rounded up)");
    it.todo("2 runes and 1 moonstone -> 75 G base premium (no block: different types) -> premium 88 G (75 + 7.5 + 5 = 87.5)");
    it.todo("3 runes and 3 moonstones -> 120 G base premium (two separate blocks) -> premium 137 G (120 + 12 + 5)");
    it.todo(
      "intermediate amounts stay fractional, only the final premium is rounded -> follow-up contract for 1 rune: 25 + 2.5 - 3.75 + 5 = 28.75 -> premium 29 G (not 30)",
    );
  });

  describe("claim", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G (full reimbursement minus 100 G deductible)");
    it.todo("rune, damage 200 G -> payout 100 G (no special clause applies)");
    it.todo(
      "damage below the deductible, sword damage 50 G -> payout 0 G (chosen reading: the deductible never makes a payout negative)",
    );
    it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies)");
    it.todo("steel sword, enchantment 7, damage 1000 G -> payout 900 G (below the enchantment 8 threshold)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (the 50 % rule wins)");
