import { describe, expect, it } from "vitest";
import { processScenario } from "./claim-office.js";

// Unless a test says otherwise, the customer is a newcomer (0 years with MHPCO)
// and the quote is the customer's first contract, so the premium is
// policy base premium + item surcharges + 10 % first insurance + 5 G fee.
//
// Rejection contract: the specification only defines the CLI outcome (non-zero
// exit status, error description on stderr). Chosen reading for the scenario
// processor: a rejected step throws an Error; type and message are unspecified.

const newcomer = { yearsWithMHPCO: 0 };

describe("MHPCO claim office", () => {
  describe("quote", () => {
    it("empty item list -> premium 5 G (only the processing fee)", () => {
      const outcome = processScenario({ customer: newcomer, steps: [{ op: "quote", items: [] }] });

      expect(outcome).toEqual({ results: [{ premium: 5 }] });
    });
    it.todo("sword -> 100 G base premium -> premium 115 G (100 + 10 first insurance + 5 fee)");
    it.todo("amulet -> 60 G base premium -> premium 71 G (60 + 6 + 5)");
    it.todo("staff -> 80 G base premium -> premium 93 G (80 + 8 + 5)");
    it.todo("potion -> 40 G base premium -> premium 49 G (40 + 4 + 5)");
    it.todo("sword and amulet -> policy base premium 160 G -> premium 181 G (160 + 16 + 5)");
    it.todo("item with an unknown type (broomstick) -> the quote is rejected by throwing an Error");
    it.todo("newcomer with a cursed sword (steel, enchantment 3) -> premium 165 G (100 + 50 curse + 10 + 5)");
    it.todo(
      "cursed sword and plain amulet -> curse surcharge 50 G on the sword only -> premium 231 G (160 + 50 + 16 + 5)",
    );

