const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;
const ONE_HUNDRED_PERCENT = 100;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / ONE_HUNDRED_PERCENT;
}

function quotePremium(items: Item[]): number {
  const policyBasePremium = items.length * SWORD_BASE_PREMIUM;
  return policyBasePremium + percentOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
}

export function processScenario(scenario: Scenario): ScenarioOutcome {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}

