const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25 };
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

export function basePremiumOf(itemType: string): number {
  if (!Object.hasOwn(BASE_PREMIUM_BY_ITEM_TYPE, itemType)) {
    throw new Error(`Unknown item type: ${itemType}`);
  }
  return BASE_PREMIUM_BY_ITEM_TYPE[itemType];
}

function sumOfBasePremiums(itemTypes: string[]): number {
  return itemTypes.reduce((sum, itemType) => sum + basePremiumOf(itemType), 0);
}

export function policyBasePremium(itemTypes: string[]): number {
  const runes = itemTypes.filter((itemType) => itemType === "rune");
  if (runes.length !== BLOCK_SIZE) {
    return sumOfBasePremiums(itemTypes);
  }
  const otherItemTypes = itemTypes.filter((itemType) => itemType !== "rune");
  return BLOCK_BASE_PREMIUM + sumOfBasePremiums(otherItemTypes);
}
EOF
