import type { Item } from "./premium.js";

export interface Damage {
  itemType: string;
  amount: number;
}

const DEDUCTIBLE = 100;
const HIGH_ENCHANTMENT_CLAUSE_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
const ONE_HUNDRED_PERCENT = 100;

function reimbursement(damagedItem: Item | undefined, amount: number): number {
  if ((damagedItem?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_LEVEL) {
    return (amount * HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT) / ONE_HUNDRED_PERCENT;
  }
  return amount;
}

function damagePayout(insuredItems: Item[], damage: Damage): number {
  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
  return Math.max(0, reimbursement(damagedItem, damage.amount) - DEDUCTIBLE);
}

export function claimPayout(insuredItems: Item[], damages: Damage[]): number {
  return damages.reduce((sum, damage) => sum + damagePayout(insuredItems, damage), 0);
}
EOF
