=== src/claim-office.ts
import { issuePolicy, settleClaim, type ClaimSettlement, type Damage, type Policy } from "./claim.js";
import type { Item } from "./item.js";
import { quotePremium, type Customer } from "./premium.js";

export type { Customer, Damage, Item };

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult | ClaimSettlement;

export interface ScenarioOutcome {
  results: StepResult[];
}

function policyCreatedBy(policies: Map<number, Policy>, step: number): Policy {
  const policy = policies.get(step);
  if (policy === undefined) {
    throw new Error(`Step ${step} did not create a policy`);
  }
  return policy;
}

export function processScenario(scenario: Scenario): ScenarioOutcome {
  const policies = new Map<number, Policy>();
  const results = scenario.steps.map((step, stepIndex) => {
    if (step.op === "claim") {
      return settleClaim(policyCreatedBy(policies, step.policy), step.incident.damages);
    }
    const previousContracts = policies.size;
    policies.set(stepIndex, issuePolicy(step.items));
    return { premium: quotePremium(step.items, scenario.customer, previousContracts) };
  });
  return { results };
}
=== src/premium.ts
import type { Item } from "./item.js";
import { percentOf } from "./percent.js";
import { basePremiumOf, policyBasePremium } from "./price-list.js";
import { roundPremiumInMhpcoFavor } from "./rounding.js";

export interface Customer {
  yearsWithMHPCO: number;
}

const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const LONG_STANDING_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
const PROCESSING_FEE = 5;

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function riskSurchargePercent(item: Item): number {
  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return cursePercent + highEnchantmentPercent;
}

function riskSurcharge(item: Item): number {
  return percentOf(basePremiumOf(item.type), riskSurchargePercent(item));
}

function isLongStanding(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LONG_STANDING_YEARS;
}

function isFollowUpContract(previousContracts: number): boolean {
  return previousContracts > 0;
}

function policyWideModifierPercent(customer: Customer, previousContracts: number): number {
  const loyaltyDiscountPercent = isLongStanding(customer) ? LOYALTY_DISCOUNT_PERCENT : 0;
  const followUpDiscountPercent = isFollowUpContract(previousContracts) ? FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT : 0;
  return FIRST_INSURANCE_SURCHARGE_PERCENT - loyaltyDiscountPercent - followUpDiscountPercent;
}

export function quotePremium(items: Item[], customer: Customer, previousContracts: number): number {
  const basePremium = policyBasePremium(items.map((item) => item.type));
  const riskSurcharges = items.reduce((sum, item) => sum + riskSurcharge(item), 0);
  const policyWideModifiers = percentOf(basePremium, policyWideModifierPercent(customer, previousContracts));
  return roundPremiumInMhpcoFavor(basePremium + riskSurcharges + policyWideModifiers + PROCESSING_FEE);
}
=== src/price-list.ts
interface MainItemRow {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEMS: Record<string, MainItemRow> = {
  sword: { insuranceValue: 1000, basePremium: 100 },
  amulet: { insuranceValue: 600, basePremium: 60 },
  staff: { insuranceValue: 800, basePremium: 80 },
  potion: { insuranceValue: 400, basePremium: 40 },
};
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_INSURANCE_VALUE = 250;
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function isComponent(itemType: string): boolean {
  return COMPONENT_TYPES.includes(itemType);
}

function mainItem(itemType: string): MainItemRow {
  if (!Object.hasOwn(MAIN_ITEMS, itemType)) {
    throw new Error(`Unknown item type: ${itemType}`);
  }
  return MAIN_ITEMS[itemType];
}

export function basePremiumOf(itemType: string): number {
  return isComponent(itemType) ? COMPONENT_BASE_PREMIUM : mainItem(itemType).basePremium;
}

function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
}

function mainItemsBasePremium(itemTypes: string[]): number {
  return itemTypes
    .filter((itemType) => !isComponent(itemType))
    .reduce((sum, itemType) => sum + basePremiumOf(itemType), 0);
}

// "Alike" components are components of exactly the same type.
function componentsBasePremium(itemTypes: string[]): number {
  return COMPONENT_TYPES.reduce((sum, componentType) => {
    const alikeComponents = itemTypes.filter((itemType) => itemType === componentType);
    return sum + alikeComponentsBasePremium(alikeComponents.length);
  }, 0);
}

export function policyBasePremium(itemTypes: string[]): number {
  return mainItemsBasePremium(itemTypes) + componentsBasePremium(itemTypes);
}

function insuranceValueOf(itemType: string): number {
  return isComponent(itemType) ? COMPONENT_INSURANCE_VALUE : mainItem(itemType).insuranceValue;
}

export function insuranceSum(itemTypes: string[]): number {
  return itemTypes.reduce((sum, itemType) => sum + insuranceValueOf(itemType), 0);
}
=== src/claim.ts
import { damagePayout } from "./damage-payout.js";
import type { Item } from "./item.js";
import { insuranceSum } from "./price-list.js";
import { roundPayoutInMhpcoFavor } from "./rounding.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Policy {
  insuredItems: Item[];
  remainingCap: number;
}

export interface ClaimSettlement {
  payout: number;
  remainingCap: number;
}

const CAP_AS_MULTIPLE_OF_INSURANCE_SUM = 2;

function takeDamagedItem(undamagedItems: Item[], itemType: string): Item {
  const position = undamagedItems.findIndex((item) => item.type === itemType);
  if (position === -1) {
    throw new Error(`The policy covers no further item of type: ${itemType}`);
  }
  return undamagedItems.splice(position, 1)[0];
}

